public class MemoryDemonstration {
    private static final int MB = 1024 * 1024;

    public static void recursiveStackOverflow(int depth) {
        // Each recursive call pushes a new frame to the thread-private JVM Stack
        // Unbounded recursion inevitably triggers a StackOverflowError
        double[] localArray = new double[102];
        recursiveStackOverflow(depth + 1);
    }

    public static void main(String[] args) {
        // Instances and arrays are allocated on the Heap
        byte[] heavyHeapAllocation = new byte[64 * MB];

        try {
            recursiveStackOverflow(0);
        } catch (StackOverflowError e) {
            System.err.println("Caught stack overflow at depth: limit reached on JVM Stack.");
        }
    }
}
